// Filtro de relevancia (Minimum Score escalonado) + contrato de retorno del Worker · v3
// v2: devuelve sección y cita determinista.
// v3: zona gris [min_score_gris, min_score): pasa SOLO el fragmento #1 marcado como confianza media;
//     la regla "No sé" del prompt verifica que el dato esté explícito.
const p = $('Parametros RAG').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && r.document);

const frags = filas.map(r => {
  const bruto = Number(r.score);
  // PGVector (cosine) devuelve DISTANCIA: 0 = idéntico. Se convierte a similitud 0..1.
  const similitud = p.score_es_distancia ? 1 - bruto : bruto;
  const m = r.document.metadata || {};
  const fuente = m.file_name || 'sin_nombre';
  const revision = m.revision || '';
  const seccion = m.seccion || '';
  return {
    fuente, revision, seccion,
    titulo: m.titulo || '',
    cita: `[Manual: ${fuente} · Rev. ${revision} · Secc. ${seccion}]`,
    similitud: Math.round(similitud * 1000) / 1000,
    score_bruto: Math.round(bruto * 1000) / 1000,
    texto: r.document.pageContent
  };
}).sort((a, b) => b.similitud - a.similitud);

const gris = Number(p.min_score_gris ?? p.min_score);
let aprobados = frags.filter(f => f.similitud >= p.min_score).map(f => ({ ...f, confianza: 'alta' }));
let status = aprobados.length ? 'ok' : 'no_match';
if (!aprobados.length && frags[0] && frags[0].similitud >= gris) {
  aprobados = [{ ...frags[0], confianza: 'media' }];
  status = 'ok_confianza_media';
}

return [{ json: {
  status,
  worker: 'procedimientos_panol',
  params: { consulta: p.consulta, top_k: p.top_k, min_score: p.min_score, min_score_gris: gris },
  data: {
    fragmentos: aprobados.map(({ score_bruto, ...f }) => f),
    recuperados: frags.length,
    descartados_por_umbral: frags.length - aprobados.length,
    detalle_scores: frags.map(f => ({ seccion: f.seccion, similitud: f.similitud, titulo: f.titulo }))
  },
  error_message: status === 'no_match' ? 'Ningún fragmento supera el umbral mínimo: responder "No sé".'
    : status === 'ok_confianza_media' ? 'Confianza media: verificá que el fragmento contenga la regla que responde la pregunta. Si la contiene, respondé normalmente con su cita.' : null
}}];
